unsigned patch_jump_insn(void *insnbuf, const void *target, unsigned long addr, unsigned len) {
    unsigned long offset;
    unsigned char *ip = insnbuf;

    if (len < 5) {
#ifdef CONFIG_RETPOLINE
        // Warning: Jump instruction requires at least 5 bytes
#endif
        return len;
    }

    offset = (unsigned long)target - (addr + 5);
    *ip++ = 0xe9; // Opcode for near jump
    *(unsigned long *)ip = offset;

    return 5;
}

unsigned patch_jump_insn(void *insnbuf, const void *target, unsigned long addr, unsigned len)
{
    long offset = (long)target - (long)addr - 5;
    if (len < 5) {
#ifdef CONFIG_RETPOLINE
        pr_warn("Jump buffer too small for patching\n");
#endif
        return len;
    }
    *(uint8_t *)insnbuf = 0xE9; // Opcode for near jump
    *(long *)((uint8_t *)insnbuf + 1) = offset;
    return 5;
}

